DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.wa_accept_request(uuid)'::regprocedure) INTO definition; definition=replace(definition,'total=total+(p->>''price'')::numeric*(line->>''qty'')::integer;', 'IF line->>''quotedPrice'' IS NULL OR (line->>''quotedPrice'')::numeric IS DISTINCT FROM (p->>''price'')::numeric THEN RAISE EXCEPTION ''Preço alterado; peça nova confirmação''; END IF; total=total+(p->>''price'')::numeric*(line->>''qty'')::integer;'); EXECUTE definition; END $$;